// ============================================================================
// Aula 9: Boolean & Coerção de Tipos - Rodrigo Branas
// ============================================================================

console.info('1. O TIPO PRIMITIVO BOOLEANO');
console.log('typeof true:', typeof true);   // 'boolean'
console.log('typeof false:', typeof false); // 'boolean'

console.info('\n2. A ARMADILHA DO CONSTRUTOR new Boolean()');
const objetoFalso = new Boolean(false);
console.log('typeof new Boolean(false):', typeof objetoFalso); // 'object'

// Por que isso é perigoso em condicionais?
if (objetoFalso) {
  console.warn('⚠️ ALERTA: new Boolean(false) entrou no IF porque todo OBJETO é truthy!');
} else {
  console.log('Não entra aqui!');
}

console.info('\n3. CONVERSÃO SEGURA COM Boolean() e DUPLA NEGAÇÃO (!!)');
console.log('Boolean(0):', Boolean(0));         // false
console.log('Boolean(1):', Boolean(1));         // true
console.log('!!"":', !!"");                     // false
console.log('!!"texto":', !!"texto");           // true

console.info('\n4. OS 6 VALORES FALSY CANÔNICOS');
console.log('0:', !!0);
console.log('-0:', !!-0);
console.log('null:', !!null);
console.log('undefined:', !!undefined);
console.log('NaN:', !!NaN);
console.log('"":', !!"");
console.log('false:', !!false);

console.info('\n5. VALORES TRUTHY SURPREENDENTES');
console.log('Array vazio []:', !![]);           // true (objeto)
console.log('Objeto vazio {}:', !!{});         // true (objeto)
console.log('String "0":', !!"0");             // true (string não-vazia)
console.log('String "false":', !!"false");     // true (string não-vazia)
console.log('new Date():', !!new Date());       // true

console.info('\n6. OPERADOR TERNÁRIO');
const valor = 1;
const resultado = Boolean(valor) ? 'Verdadeiro' : 'Falso';
console.log('Resultado do ternário para valor=1:', resultado);
